@MainActor func transient_PackageOval_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,          
       _ self_x : CanariLength,                         
       _ self_y : CanariLength,                         
       _ self_width : CanariLength,                     
       _ self_height : CanariLength,                    
       _ self_PackageObject_knobSize : Double
) -> EBShape {
//--- START OF USER ZONE 2
  var shape = EBShape ()
  let x = self_x
  let y = self_y
  let width = self_width
  let height = self_height
  var bp : BezierPath
  if (self_width <= .zero) && (self_height <= .zero) { // Oval is a point
    bp = BezierPath ()
    bp.move (to: NSPoint (x: x, y: y))
    bp.line (to: NSPoint (x: x, y: y))
  }else if self_width <= .zero { // Vertical line
    bp = BezierPath ()
    bp.move (to: NSPoint (x: x, y: y))
    bp.line (to: NSPoint (x: x, y: y + height))
  }else if self_height <= .zero { // Horizontal line
    bp = BezierPath ()
    bp.move (to: NSPoint (x: x, y: y))
    bp.line (to: NSPoint (x: x + width, y: y))
  }else{
    let r = CanariRect (left: x, bottom: y, width: width, height: height)
    bp = BezierPath (ovalIn: r)
  }
  bp.lineWidth = CanariLength.pt (0.25)
  shape.add (stroke: [bp], prefs_selectionHiliteColor)
  shape.add (knobAt:  CanariPoint (x: x + width / 2.0, y: y), knobIndex: PACKAGE_OVAL_BOTTOM, .diamond, .pt (self_PackageObject_knobSize))
  shape.add (knobAt:  CanariPoint (x: x, y: y + height / 2.0), knobIndex: PACKAGE_OVAL_LEFT, .diamond, .pt (self_PackageObject_knobSize))
  shape.add (knobAt:  CanariPoint (x: x + width / 2.0, y: y + height), knobIndex: PACKAGE_OVAL_TOP, .diamond, .pt (self_PackageObject_knobSize))
  shape.add (knobAt:  CanariPoint (x: x + width, y: y + height / 2.0), knobIndex: PACKAGE_OVAL_RIGHT, .diamond, .pt (self_PackageObject_knobSize))
  return shape
//--- END OF USER ZONE 2
}

